import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"The Week 14 Debate","description":"","frontmatter":{"source":"weeks/14-evidence-and-responsibility/debate.md"},"headers":[],"relativePath":"weeks/14-evidence-and-responsibility/debate.md","filePath":"weeks/14-evidence-and-responsibility/debate.md"}'),n={name:"weeks/14-evidence-and-responsibility/debate.md"};function s(i,e,d,l,h,c){return r(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-week-14-debate" tabindex="-1">The Week 14 Debate <a class="header-anchor" href="#the-week-14-debate" aria-label="Permalink to &quot;The Week 14 Debate&quot;">​</a></h1><blockquote><p>Five motions, five eight-minute rounds, and a rule that every claim names its source. Persuasion and evidence are scored separately, so we can see when they disagree.</p></blockquote><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>When</strong></td><td>The week 14 Seminar, after the due-date quiz and an 8-minute talk on reading evidence</td></tr><tr><td><strong>Format</strong></td><td>Five rounds of 8 minutes, one motion each, with a vote before and after every round</td></tr><tr><td><strong>Roles</strong></td><td>Two speakers <strong>for</strong>, two <strong>against</strong>, one <strong>evidence judge</strong> per round; everyone else is the <strong>floor</strong> (<a href="#roles">roles</a>)</td></tr><tr><td><strong>Sides</strong></td><td>Assigned on Canvas after the week 13 Seminar. You may be arguing against your own view: that&#39;s the exercise</td></tr><tr><td><strong>Preparation</strong></td><td>Speakers post three <a href="#evidence-cards">evidence cards</a> in the Canvas debate thread by 11:59 pm the night before; judges post the three numbers they&#39;ll check</td></tr><tr><td><strong>AI use</strong></td><td>🔴 AI off for cards, speeches, rulings and questions. Read the sources yourself</td></tr><tr><td><strong>Graded as</strong></td><td>Seminar participation, as usual (<a href="./../../assessment/rubrics.html#seminar-participation-2-points-per-seminar">rubric</a>). The scorecards are feedback, not grades</td></tr></tbody></table><h2 id="the-motions" tabindex="-1">The motions <a class="header-anchor" href="#the-motions" aria-label="Permalink to &quot;The motions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Round</th><th>Motion</th><th>Evidence area</th></tr></thead><tbody><tr><td>1</td><td><em>This house believes AI coding agents make professional developers faster.</em></td><td>Productivity</td></tr><tr><td>2</td><td><em>This house believes the quality cost of AI-assisted code outweighs its output gains.</em></td><td>Quality</td></tr><tr><td>3</td><td><em>This house would switch coding agents off for a developer&#39;s first year, in a degree or in a job.</em></td><td>Skills and critical thinking</td></tr><tr><td>4</td><td><em>This house believes open-source projects should decline AI-generated contributions, as QEMU does, rather than accept disclosed ones, as LLVM does.</em></td><td>Maintainers&#39; policies and attribution</td></tr><tr><td>5</td><td><em>This house believes that, for AI-assisted work on public open-source code, disclosure and human review are enough to handle licensing and privacy.</em></td><td>Licensing, provenance and privacy</td></tr></tbody></table><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>How many per round</th><th>What you do</th></tr></thead><tbody><tr><td><strong>Speaker for</strong></td><td>2</td><td>Speaker 1 opens (90 seconds); speaker 2 closes (45 seconds), answering what the floor and the other side raised</td></tr><tr><td><strong>Speaker against</strong></td><td>2</td><td>The same, for the other side</td></tr><tr><td><strong>Evidence judge</strong></td><td>1</td><td>Reads the round&#39;s source pack in advance, scores every claim on the <a href="#scoring">scorecard</a>, and gives a 60-second <strong>evidence ruling</strong>: the best-supported claim, the weakest one, and one claim the evidence supports that nobody made</td></tr><tr><td><strong>Floor</strong></td><td>Everyone else</td><td>Votes; may raise one <strong>point of evidence</strong> per round; asks questions in the floor block</td></tr><tr><td><strong>Moderator</strong></td><td>The instructor</td><td>Keeps time, enforces the rules, runs the votes</td></tr></tbody></table><p>With about 25 students, everyone has one role in one round. With fewer than 15, use one speaker per side (opening and closing) and merge rounds 1 and 2 into <em>&quot;This house believes AI coding agents make software teams more productive&quot;</em>. With more than 25, add a second judge per round. CS [5xxx] students are judges by default. If a graduate paper presentation is scheduled this week, it replaces the round on its topic: the presenter is the round&#39;s expert witness and the discussant opens its floor (<a href="./../../graduate/paper-presentations.html">paper presentations</a>).</p><h2 id="a-round-minute-by-minute" tabindex="-1">A round, minute by minute <a class="header-anchor" href="#a-round-minute-by-minute" aria-label="Permalink to &quot;A round, minute by minute&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Who</th><th>Time</th></tr></thead><tbody><tr><td>Opening for</td><td>Speaker 1 for</td><td>1:30</td></tr><tr><td>Opening against</td><td>Speaker 1 against</td><td>1:30</td></tr><tr><td>Floor: points of evidence and questions; either side answers</td><td>Floor</td><td>2:00</td></tr><tr><td>Closing against</td><td>Speaker 2 against</td><td>0:45</td></tr><tr><td>Closing for</td><td>Speaker 2 for</td><td>0:45</td></tr><tr><td>Evidence ruling</td><td>Judge</td><td>1:00</td></tr><tr><td>Second vote</td><td>Everyone</td><td>0:30</td></tr></tbody></table><p>Everyone votes on all five motions before round 1 (a Canvas poll, or hands). The <strong>swing</strong> for each motion is the change between the two votes.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li><strong>Name the source in the sentence.</strong> &quot;METR&#39;s 2025 trial found…&quot;, not &quot;studies show…&quot;.</li><li><strong>Label opinion as opinion.</strong> &quot;In my opinion…&quot; or &quot;I infer…&quot; is allowed and never penalized; opinion presented as fact is.</li><li><strong>Say what kind of source it is.</strong> A preprint is a preprint; a vendor&#39;s post is the vendor&#39;s; a survey measures what people report.</li><li><strong>Numbers come with their uncertainty</strong> when the source gives one (a confidence interval or a standard error).</li><li><strong>Points of evidence.</strong> Anyone on the floor may say &quot;Point of evidence&quot; once per round. The speaker has 15 seconds to name the source; if they can&#39;t, the judge strikes the claim.</li><li><strong>Claims about our own code, agents or tools are tagged</strong> <a href="./../../resources/glossary.html#observed-and-inferred">observed or inferred</a>.</li><li><strong>Argue evidence, not people.</strong> No comments on classmates&#39; work, and maintainers are discussed only through what their projects published.</li><li><strong>Time is strict.</strong> The moderator stops you mid-sentence; that&#39;s what the closing is for.</li></ol><h2 id="evidence-cards" tabindex="-1">Evidence cards <a class="header-anchor" href="#evidence-cards" aria-label="Permalink to &quot;Evidence cards&quot;">​</a></h2><p>Each speaker posts <strong>three cards</strong> in the Canvas debate thread by 11:59 pm the night before the Seminar, so the judge can check them. At least one must come from a peer-reviewed paper or a primary document (a policy, a court record), and at least one must be <strong>against interest</strong>: a real limitation of your own side&#39;s best evidence. Conceding it out loud earns a point.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Card [round]-[for/against]-[1-3] · [GitHub username]</span></span>
<span class="line"><span>Claim (the sentence you will say):</span></span>
<span class="line"><span>Source: [authors or project, title, venue or kind (peer-reviewed, preprint, vendor, policy, news, court), year, link]</span></span>
<span class="line"><span>Design: [randomized trial · field experiment · difference-in-differences · observational · survey · interviews · benchmark · policy text · court record]</span></span>
<span class="line"><span>Sample: [who or what, and how many]</span></span>
<span class="line"><span>Number: [the figure, with its uncertainty if the source gives one]</span></span>
<span class="line"><span>Limit: [one thing this source can&#39;t show]</span></span>
<span class="line"><span>Against interest: [yes / no]</span></span></code></pre></div><h2 id="scoring" tabindex="-1">Scoring <a class="header-anchor" href="#scoring" aria-label="Permalink to &quot;Scoring&quot;">​</a></h2><p>The judge scores every claim a speaker makes aloud. The side with more evidence points <strong>wins the evidence</strong>; the swing is reported separately.</p><table tabindex="0"><thead><tr><th>Points</th><th>When</th></tr></thead><tbody><tr><td><strong>+2</strong></td><td>Source named, number accurate (with its uncertainty where given), design described correctly</td></tr><tr><td><strong>+1</strong></td><td>Source named, but the number is missing or rounded in a misleading way</td></tr><tr><td><strong>+1</strong></td><td>A real limitation of your own evidence, conceded without being asked</td></tr><tr><td><strong>0</strong></td><td>Opinion, labeled as opinion</td></tr><tr><td><strong>−1</strong></td><td>A claim presented as fact without a source, or struck after a point of evidence</td></tr><tr><td><strong>−2</strong></td><td>Misstated evidence: a wrong number, a correlation stated as a cause, a preprint called peer-reviewed, a vendor claim called independent</td></tr></tbody></table><h2 id="source-packs" tabindex="-1">Source packs <a class="header-anchor" href="#source-packs" aria-label="Permalink to &quot;Source packs&quot;">​</a></h2><p>Starting points, with the numbers as recorded in the course&#39;s <a href="./../../research/notes/evidence-senior.html">evidence notes</a>. They are not a script: read the source before you cite it, and you may bring others from the <a href="./../../resources/reading-list.html#week-14--evidence-and-responsibility">reading list</a>.</p><h3 id="round-1--productivity" tabindex="-1">Round 1 — Productivity <a class="header-anchor" href="#round-1--productivity" aria-label="Permalink to &quot;Round 1 — Productivity&quot;">​</a></h3><ul><li><strong>METR&#39;s 2025 randomized trial</strong> (<a href="https://arxiv.org/abs/2507.09089" target="_blank" rel="noreferrer">paper</a>; <a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">summary</a>): 16 experienced developers, 246 tasks in large, mature repositories they knew well. Tasks with AI allowed took <strong>19% longer</strong> (interval roughly +2% to +39%); developers had forecast a 24% speedup and afterwards believed in about 20%.</li><li><strong>METR&#39;s February 2026 update</strong> (<a href="https://metr.org/blog/2026-02-24-uplift-update/" target="_blank" rel="noreferrer">post</a>): 57 developers, 800+ tasks. Task time <strong>−18%</strong> for returning developers (interval −38% to +9%) and <strong>−4%</strong> for new ones (−15% to +9%). Some developers declined or dropped out rather than work without AI, and 30–50% withheld tasks they thought needed AI, so METR calls the estimates unreliable and the true speedup probably underestimated.</li><li><strong>Cui et al.</strong>, <em>Management Science</em> 2026 (<a href="https://pubsonline.informs.org/doi/fpi/10.1287/mnsc.2025.00535" target="_blank" rel="noreferrer">paper</a>): randomized rollouts at three firms, 4,867 developers: <strong>+26.08% completed tasks (SE 10.3%)</strong>; juniors +27–39%, seniors +8–13%; about 60% adoption after a year; quality not observed.</li><li><strong>Paradis et al.</strong> (Google, preprint; <a href="https://arxiv.org/abs/2410.12944" target="_blank" rel="noreferrer">arXiv</a>): 96 engineers, about 21% less time, wide interval.</li><li><strong>Murphy-Hill et al.</strong> (Microsoft, preprint; <a href="https://arxiv.org/abs/2607.01418" target="_blank" rel="noreferrer">arXiv</a>): adopters of command-line agents merged about 24% more PRs than their counterfactual, for four months.</li><li><strong>DORA 2025</strong> (<a href="https://dora.dev/dora-report-2025/" target="_blank" rel="noreferrer">report</a>): about 5,000 respondents; 90% use AI at work and over 80% believe it raised their productivity; adoption correlates with higher throughput and lower stability. A survey, not a trial.</li><li><strong>METR&#39;s 2026 survey</strong> (<a href="https://metr.org/blog/2026-05-11-ai-usage-survey/" target="_blank" rel="noreferrer">post</a>): 349 workers reported a median of about 3× speed; METR notes earlier work found people overestimate time savings by about 40 percentage points.</li></ul><h3 id="round-2--quality" tabindex="-1">Round 2 — Quality <a class="header-anchor" href="#round-2--quality" aria-label="Permalink to &quot;Round 2 — Quality&quot;">​</a></h3><ul><li><strong>He et al.</strong>, MSR 2026 (<a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">arXiv</a>): 807 Cursor-adopting repositories against 1,380 matched controls. Lines added rose <strong>281%</strong> in the first month and the gain was gone after about two months; static-analysis warnings (<strong>+29.7%</strong>) and complexity (<strong>+40.7%</strong> in Table 2, <strong>25.1%</strong> in the text) stayed up.</li><li><strong>Denisov-Blanch et al.</strong> (preprint; <a href="https://arxiv.org/abs/2608.25241" target="_blank" rel="noreferrer">arXiv</a>): in 441 repositories, agents raised commits 28–38%; complexity rose <strong>53%</strong> in agent-first repositories with no committed AI configuration file vs <strong>27%</strong> with one. Observational.</li><li><strong>Borg et al.</strong>, ICSME 2025 registered report (<a href="https://arxiv.org/abs/2507.00788" target="_blank" rel="noreferrer">arXiv</a>): AI cut completion time 30.7%, but other developers later evolving that code showed <strong>no significant difference</strong> in time or quality.</li><li><strong>Watanabe et al.</strong> (preprint; <a href="https://arxiv.org/abs/2509.14745" target="_blank" rel="noreferrer">arXiv</a>): of 567 agent PRs, <strong>83.8% merged</strong>, and <strong>45.1% of those</strong> needed further changes.</li><li><strong>METR, maintainers vs graders</strong> (<a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">note</a>): four maintainers reviewed 296 test-passing agent PRs; their merge rate ran <strong>24.2 points</strong> below the automated grader.</li></ul><h3 id="round-3--skills-and-critical-thinking" tabindex="-1">Round 3 — Skills and critical thinking <a class="header-anchor" href="#round-3--skills-and-critical-thinking" aria-label="Permalink to &quot;Round 3 — Skills and critical thinking&quot;">​</a></h3><ul><li><strong>Shen &amp; Tamkin</strong> (Anthropic randomized trial, preprint; <a href="https://arxiv.org/abs/2601.20245" target="_blank" rel="noreferrer">arXiv</a>; <a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">summary</a>): 52 mostly junior engineers learning a new library. Quiz scores <strong>50% with AI vs 67% without</strong> (Cohen&#39;s d = 0.738), the biggest gap on debugging; the AI group was not significantly faster. Participants who asked for explanations scored higher.</li><li><strong>Balepur et al.</strong> (preprint; <a href="https://arxiv.org/abs/2607.26375" target="_blank" rel="noreferrer">arXiv</a>): 54 students finished faster with an editing agent but understood less and extended their code worse without AI, and still preferred the agent. No effect sizes in the abstract.</li><li><strong>Lee et al.</strong>, CHI 2025 (<a href="https://advait.org/files/lee_2025_ai_critical_thinking_survey.pdf" target="_blank" rel="noreferrer">PDF</a>): 319 knowledge workers, 936 examples: higher confidence in the AI predicted <strong>less</strong> critical thinking; higher self-confidence predicted more. Self-reported.</li><li><strong>Cui et al.</strong> (round 1): juniors gained the most speed.</li><li><strong>Brynjolfsson, Chandar &amp; Chen</strong> (<a href="https://digitaleconomy.stanford.edu/news/canaries-interest-rates-and-timinga-more-on-recent-drivers-of-employment-changes-for-young-workers" target="_blank" rel="noreferrer">follow-up</a>): employment of developers aged 22–25 down nearly 20% from the late-2022 peak; under stricter controls the decline is significant only after 2024, and partly driven by non-AI factors.</li><li><strong>Yu &amp; Moon</strong>, AIES 2026 (<a href="https://arxiv.org/abs/2607.17067" target="_blank" rel="noreferrer">arXiv</a>): 14 interviews describing &quot;Absorption&quot;, entry-level work folded into senior-plus-AI workflows.</li></ul><h3 id="round-4--maintainers-policies-and-attribution" tabindex="-1">Round 4 — Maintainers&#39; policies and attribution <a class="header-anchor" href="#round-4--maintainers-policies-and-attribution" aria-label="Permalink to &quot;Round 4 — Maintainers&#39; policies and attribution&quot;">​</a></h3><ul><li><strong>QEMU</strong> (<a href="https://www.qemu.org/docs/master/devel/code-provenance.html" target="_blank" rel="noreferrer">policy</a>; <a href="./../../resources/case-studies.html#e1-qemu-decline-and-a-proposal-to-relax">case E1</a>): declines contributions believed to include AI-generated content, citing copyright and certificate-of-origin uncertainty; a May 2026 proposal to allow small changes with an <code>AI-used-for:</code> trailer has no recorded decision.</li><li><strong>Ghostty</strong> (<a href="https://github.com/ghostty-org/ghostty/blob/main/AI_POLICY.md" target="_blank" rel="noreferrer">policy</a>; <a href="./../../resources/case-studies.html#e2-ghostty-disclose-everything-or-be-denounced">case E2</a>): all AI use disclosed; contributors explain changes without AI; a public denouncement list.</li><li><strong>LLVM</strong> (<a href="https://github.com/llvm/llvm-project/blob/main/llvm/docs/AIToolPolicy.md" target="_blank" rel="noreferrer">policy</a>; <a href="./../../resources/case-studies.html#e3-llvm-a-human-in-the-loop-and-an-assisted-by-trailer">case E3</a>): read and review all generated code, an <code>Assisted-by:</code> trailer, self-written PR descriptions, no agents acting without human approval.</li><li><strong>The Linux kernel</strong> (<a href="https://github.com/torvalds/linux/blob/master/Documentation/process/coding-assistants.rst" target="_blank" rel="noreferrer">policy</a>; <a href="https://hackaday.com/2026/10/15/linux-kernel-drops-ai-tag-requirement-uses-meta-ai-for-code-reviews/" target="_blank" rel="noreferrer">Hackaday</a>; <a href="./../../resources/case-studies.html#e4-the-linux-kernel-drops-its-ai-tag">case E4</a>): &quot;AI agents MUST NOT add Signed-off-by tags&quot;; in October 2026 maintainers dropped the AI tag requirement, while networking maintainers run several models on each patch for review.</li><li><strong>Hora &amp; Robbes</strong> (preprint; <a href="https://arxiv.org/abs/2605.16706" target="_blank" rel="noreferrer">arXiv</a>): of 118 policies in 1,000 popular repositories, <strong>78%</strong> allow AI-assisted contributions, 22% discourage AI use, <strong>51%</strong> require disclosure and <strong>74%</strong> a human in the loop.</li><li><strong>The cost to maintainers</strong> (<a href="./../../resources/case-studies.html#e7-platforms-push-back-pr-caps-and-hacktoberfest">case E7</a>): Hacktoberfest 2026 dropped its PR challenge after &quot;a massive flood of activity and burnout&quot;; curl ended its bug bounty.</li><li><strong>Horikawa et al.</strong> (preprint; <a href="https://arxiv.org/abs/2610.36229" target="_blank" rel="noreferrer">arXiv</a>): across 7.8M commits, detectors of agent-written commits reach precision <strong>0.332</strong> at realistic prevalence: detection &quot;cannot replace recorded attribution&quot;.</li></ul><h3 id="round-5--licensing-provenance-and-privacy" tabindex="-1">Round 5 — Licensing, provenance and privacy <a class="header-anchor" href="#round-5--licensing-provenance-and-privacy" aria-label="Permalink to &quot;Round 5 — Licensing, provenance and privacy&quot;">​</a></h3><ul><li><strong>LiCoEval</strong>, ICSE 2025 (<a href="https://arxiv.org/abs/2408.02487" target="_blank" rel="noreferrer">arXiv</a>): across 14 models, even the best produced <strong>0.88–2.01%</strong> of outputs &quot;strikingly similar&quot; to existing open-source code, and most gave inaccurate license information, especially for copyleft.</li><li><em><strong>Thaler v. Perlmutter</strong></em>, cert. denied 2026 (<a href="https://www.scotusblog.com/cases/case-files/thaler-v-perlmutter" target="_blank" rel="noreferrer">SCOTUSblog</a>): the human-authorship requirement for copyright stands; the denial is not a ruling on AI-assisted works.</li><li><em><strong>Bartz v. Anthropic</strong></em> (<a href="https://www.jurist.org/news/2026/07/judge-approves-record-1-5-billion-settlement-involving-anthropic/" target="_blank" rel="noreferrer">JURIST</a>): training on lawfully bought books was held fair use, keeping 7M+ pirated books was not; settled for <strong>$1.5B</strong>, about $3,000 per work.</li><li><strong>NetBSD and Gentoo</strong> (<a href="./../../resources/case-studies.html#e5-django-gentoo-and-netbsd-three-more-answers">case E5</a>): LLM output &quot;presumed to be tainted code&quot;; Gentoo bans it.</li><li><strong>The data rule</strong> (<a href="./../../TOOLS.html#the-data-rule">Tool Handout: The data rule</a>): several free tiers the course uses may train on prompts, some with no opt-out.</li><li><strong>PixelLeak</strong> (<a href="./../../resources/case-studies.html#a8-pixelleak-helpful-agents-publish-13000-screenshots">case A8</a>): agents asked for review screenshots created public repositories and exposed <strong>13,000+</strong> internal screenshots from 300+ organizations. No attacker.</li><li><strong>GitHub MCP and CamoLeak</strong> (<a href="./../../resources/case-studies.html#a2-github-mcp-a-public-issue-leaks-a-private-repository">A2</a>; <a href="./../../resources/case-studies.html#a4-copilot-edits-its-own-permissions-and-camoleak">A4</a>): a public issue led an agent to copy private-repository data into a public PR; hidden PR comments leaked private code through image URLs (CVSS 9.6).</li></ul><h2 id="after-the-debate" tabindex="-1">After the debate <a class="header-anchor" href="#after-the-debate" aria-label="Permalink to &quot;After the debate&quot;">​</a></h2><p>The instructor closes with what the evidence supports, round by round, and where the evidence points and the swing disagreed. If you&#39;d rather write than speak, a substantive comment in the Canvas debate thread within 24 hours counts as participation: for example, the claim that changed your mind and the source behind it.</p><p><strong>Accommodations.</strong> Speaking is never required. Anyone can take the judge role with a written ruling the moderator reads, or contribute cards that a teammate speaks to. CDAR accommodations apply as usual; tell the instructor when roles are posted.</p>`,34)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
